/** 두루마리 안의 AI 생성 문단과 반응 수를 저장합니다. */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="paragraphs") public class Paragraph { @Id private String id; @Column(nullable=false) private String roomId; @Column(nullable=false) private String scrollId; @Lob @Column(nullable=false) private String body; @Column(nullable=false) private int version; @Column(nullable=false) private int ahMatdaCount; @Column(nullable=false) private LocalDateTime createdAt; protected Paragraph(){} private Paragraph(String r,String s,String b){id=UUID.randomUUID().toString();roomId=r;scrollId=s;body=b;version=1;createdAt=LocalDateTime.now();} public static Paragraph create(String r,String s,String b){return new Paragraph(r,s,b);} public void ahMatda(){ahMatdaCount++;} public String getId(){return id;} public String getRoomId(){return roomId;} public String getScrollId(){return scrollId;} public String getBody(){return body;} public int getVersion(){return version;} public int getAhMatdaCount(){return ahMatdaCount;} public LocalDateTime getCreatedAt(){return createdAt;} }
